-- Additive migration: 13 fan-submitted dishes (Greek meze and sweets, American
-- cookies and party dips, plus bread pudding, dal baati, pelmeni, apple fritter
-- and zeppole).
-- Pool only, no schedule rows. INSERTs only, dish keyed by slug; safe to run
-- once on the live DB. All 13 came in through the player suggestion form, so
-- they are flagged is_fan_submission at the bottom (keyed by slug, never id).



-- All 13 arrived through the player suggestion form. Keyed by slug so this is
-- safe whatever ids the INSERT above happened to take. See migrations/0017.
UPDATE dishes SET is_fan_submission = 1
 WHERE slug IN ('dolmades', 'loukoumades', 'sugar-cookies', 'snickerdoodles',
                'oatmeal-raisin-cookies', 'buffalo-chicken-dip',
                'spinach-and-artichoke-dip', 'seven-layer-dip', 'bread-pudding',
                'dal-baati', 'pelmeni', 'apple-fritter', 'zeppole');
