INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='dolmades'),1,'A cold starter from the Mediterranean country at the southern end of the Balkans, where a meal often arrives as a table of small plates.'),
((SELECT id FROM dishes WHERE slug='dolmades'),2,'Cooks across the old Ottoman world have wrapped food in leaves this way for centuries, and the whole family of dishes takes its name from a Turkish verb meaning "to be stuffed".'),
((SELECT id FROM dishes WHERE slug='dolmades'),3,'Every Greek taverna keeps a tray of them in the cold case, and for a great many Americans the tinned version was their first taste of the country.'),
((SELECT id FROM dishes WHERE slug='dolmades'),4,'Grape leaves are blanched until pliable, rolled tight around rice seasoned with onion, dill and mint, then simmered under a plate with lemon and olive oil.'),
((SELECT id FROM dishes WHERE slug='dolmades'),5,'Little green cylinders of vine leaf wrapped around lemony herbed rice, served cold with a wedge of lemon.'),
((SELECT id FROM dishes WHERE slug='loukoumades'),1,'A hot dessert from the European country that gave us the marathon, the Olympic games and a great deal of honey.'),
((SELECT id FROM dishes WHERE slug='loukoumades'),2,'Fried dough soaked in honey appears in ancient Greek writing as "honey tokens", reportedly handed to the winners at the earliest Olympic games.'),
((SELECT id FROM dishes WHERE slug='loukoumades'),3,'Athens has shops that have sold nothing else since the 1920s, and the paper cones draw long queues at Greek street festivals around the world.'),
((SELECT id FROM dishes WHERE slug='loukoumades'),4,'A loose yeasted batter is dropped by the spoonful into hot oil until the balls puff and brown, then drenched in warm honey syrup and showered with cinnamon and crushed walnuts.'),
((SELECT id FROM dishes WHERE slug='loukoumades'),5,'Golden puffs of fried dough drowned in honey syrup and dusted with cinnamon and walnuts, eaten hot with a fork.'),
((SELECT id FROM dishes WHERE slug='sugar-cookies'),1,'North American, and the plainest thing in the whole bakery case.'),
((SELECT id FROM dishes WHERE slug='sugar-cookies'),2,'German settlers in Nazareth, Pennsylvania were baking the round version in the 1700s, and their town''s name is still attached to it.'),
((SELECT id FROM dishes WHERE slug='sugar-cookies'),3,'It is the one children decorate with colored icing at Christmas and leave on a plate for a visitor coming down the chimney.'),
((SELECT id FROM dishes WHERE slug='sugar-cookies'),4,'Butter and sugar are creamed with egg and vanilla into a pale dough, rolled flat, and cut into shapes before baking until barely colored.'),
((SELECT id FROM dishes WHERE slug='sugar-cookies'),5,'The plain, pale rolled cookie tasting mostly of butter and vanilla, usually cut into shapes and covered in icing.'),
((SELECT id FROM dishes WHERE slug='snickerdoodles'),1,'North American, though the ridiculous name probably crossed the Atlantic with German or Dutch settlers.'),
((SELECT id FROM dishes WHERE slug='snickerdoodles'),2,'New England cookbooks were printing the recipe by the late 1800s, and the name has been traced both to a German word for a snail-shaped noodle and to plain Yankee nonsense, with no agreement between them.'),
((SELECT id FROM dishes WHERE slug='snickerdoodles'),3,'It is the bake sale cookie that gets picked off the table first on the strength of its name alone.'),
((SELECT id FROM dishes WHERE slug='snickerdoodles'),4,'The dough is leavened with cream of tartar for a distinct tang, rolled in cinnamon sugar, and baked until it puffs and falls into a crackled top.'),
((SELECT id FROM dishes WHERE slug='snickerdoodles'),5,'The tangy, chewy cookie rolled in cinnamon sugar and baked until the top cracks.'),
((SELECT id FROM dishes WHERE slug='oatmeal-raisin-cookies'),1,'North American, and the item in the bakery case most likely to disappoint a child.'),
((SELECT id FROM dishes WHERE slug='oatmeal-raisin-cookies'),2,'A breakfast cereal company printed a version on the side of its canister around 1900, borrowing from Scottish oatcakes, and it has stayed on the box ever since.'),
((SELECT id FROM dishes WHERE slug='oatmeal-raisin-cookies'),3,'It is the internet''s favorite cruel prank, sitting on the tray looking exactly like something else until you take a bite.'),
((SELECT id FROM dishes WHERE slug='oatmeal-raisin-cookies'),4,'Rolled oats and dried grapes are folded through a brown sugar and cinnamon dough that bakes chewy rather than crisp.'),
((SELECT id FROM dishes WHERE slug='oatmeal-raisin-cookies'),5,'The chewy brown cookie packed with rolled oats and dried grapes.'),
((SELECT id FROM dishes WHERE slug='buffalo-chicken-dip'),1,'North American, served hot, and it never turns up except in front of a crowd.'),
((SELECT id FROM dishes WHERE slug='buffalo-chicken-dip'),2,'A bar in western New York state is credited with it in the 1990s, built from the same cayenne and butter sauce that made that city''s wings famous.'),
((SELECT id FROM dishes WHERE slug='buffalo-chicken-dip'),3,'It is the first thing gone at a Super Bowl party, usually before kickoff.'),
((SELECT id FROM dishes WHERE slug='buffalo-chicken-dip'),4,'Shredded poultry is stirred into softened cream cheese with cayenne pepper sauce and shredded cheddar, then baked until it bubbles at the edge of the dish.'),
((SELECT id FROM dishes WHERE slug='buffalo-chicken-dip'),5,'The bubbling orange party dip of shredded chicken, cream cheese and wing sauce, scooped up with celery sticks and chips.'),
((SELECT id FROM dishes WHERE slug='spinach-and-artichoke-dip'),1,'North American, arrives hot in a small skillet, and is ordered for the table rather than for one person.'),
((SELECT id FROM dishes WHERE slug='spinach-and-artichoke-dip'),2,'American chain restaurants put it on their starter menus in the 1980s, borrowing the idea from older French and Italian ways of creaming greens.'),
((SELECT id FROM dishes WHERE slug='spinach-and-artichoke-dip'),3,'It is the default first order at a casual restaurant, and the copycat recipes for one chain''s version are among the most searched appetizers online.'),
((SELECT id FROM dishes WHERE slug='spinach-and-artichoke-dip'),4,'A leafy green and the tender heart of a thistle are chopped into a base of cream cheese, sour cream and parmesan, then baked until brown on top.'),
((SELECT id FROM dishes WHERE slug='spinach-and-artichoke-dip'),5,'The hot, creamy green dip of chopped leaves and thistle hearts, served bubbling with tortilla chips.'),
((SELECT id FROM dishes WHERE slug='seven-layer-dip'),1,'North American, served cold, and not one thing in it is cooked.'),
((SELECT id FROM dishes WHERE slug='seven-layer-dip'),2,'Texas cooks assembled it in the 1970s out of the Tex-Mex pantry, and a clear glass dish made it famous because the stripes show through the side.'),
((SELECT id FROM dishes WHERE slug='seven-layer-dip'),3,'It is standard potluck and tailgate furniture, and whoever carries it in also carries the biggest bag of chips.'),
((SELECT id FROM dishes WHERE slug='seven-layer-dip'),4,'Refried beans go down first, then mashed avocado, sour cream, shredded cheese, tomato, black olives and scallion, each spread flat over the last.'),
((SELECT id FROM dishes WHERE slug='seven-layer-dip'),5,'The cold, striped Tex-Mex party dip built in a glass dish and counted off from beans at the bottom to olives on top.'),
((SELECT id FROM dishes WHERE slug='bread-pudding'),1,'From an island nation in northwestern Europe, where the word "pudding" covers a great deal more than it should.'),
((SELECT id FROM dishes WHERE slug='bread-pudding'),2,'English cooks were soaking stale loaves like this by the 1200s and called it the poor man''s pudding, since it was built entirely out of what was about to be thrown away.'),
((SELECT id FROM dishes WHERE slug='bread-pudding'),3,'New Orleans adopted it so completely that half the city''s restaurants finish it with a whiskey sauce.'),
((SELECT id FROM dishes WHERE slug='bread-pudding'),4,'Torn stale bread is soaked in a custard of milk, egg, sugar and vanilla with cinnamon and raisins, then baked until the top crisps and the middle still wobbles.'),
((SELECT id FROM dishes WHERE slug='bread-pudding'),5,'Stale bread baked in sweet custard until it sets, cut into a square and served warm under a pour of sauce.'),
((SELECT id FROM dishes WHERE slug='dal-baati'),1,'From a very large South Asian country, out of a desert state where food had to keep without spoiling.'),
((SELECT id FROM dishes WHERE slug='dal-baati'),2,'Rajasthan tells it as a soldier''s meal: dough balls buried in the hot sand at dawn and dug up baked at the end of the day.'),
((SELECT id FROM dishes WHERE slug='dal-baati'),3,'It is the centerpiece of Rajasthani weddings and festivals, served on a leaf plate with a bowl of clarified butter poured over the top.'),
((SELECT id FROM dishes WHERE slug='dal-baati'),4,'Hard wheat-flour balls are baked until they crack open, then crushed, soaked in ghee, and eaten with a spiced stew of lentils.'),
((SELECT id FROM dishes WHERE slug='dal-baati'),5,'Cracked, ghee-soaked wheat balls dunked into a spiced lentil stew from the Indian desert.'),
((SELECT id FROM dishes WHERE slug='pelmeni'),1,'From the largest country on earth, and traditionally made in enormous batches once winter arrives.'),
((SELECT id FROM dishes WHERE slug='pelmeni'),2,'Cooks in Siberia and the Urals took the idea from their eastern neighbours, and the name comes from a Finno-Ugric phrase meaning "ear bread", which is roughly the shape.'),
((SELECT id FROM dishes WHERE slug='pelmeni'),3,'Families would make hundreds at a time and leave them outside to freeze in the snow, which is why nobody there thinks less of you for buying the frozen bag.'),
((SELECT id FROM dishes WHERE slug='pelmeni'),4,'Thin unleavened dough is pinched around raw minced beef and pork with onion and pepper, then boiled and served with sour cream, butter or vinegar.'),
((SELECT id FROM dishes WHERE slug='pelmeni'),5,'Small boiled dumplings of thin dough around minced meat and onion, eaten by the bowlful with sour cream, from Siberia.'),
((SELECT id FROM dishes WHERE slug='apple-fritter'),1,'North American in its current form, and it sits in the doughnut case looking like something went wrong.'),
((SELECT id FROM dishes WHERE slug='apple-fritter'),2,'Frying fruit in batter is old European practice; Dutch settlers brought it to New York, where the bakery counter turned it into the craggy glazed slab sold today.'),
((SELECT id FROM dishes WHERE slug='apple-fritter'),3,'It is the item people argue is not really a doughnut, and reliably the largest thing on the tray.'),
((SELECT id FROM dishes WHERE slug='apple-fritter'),4,'Chopped orchard fruit and cinnamon are folded through a wet dough, dropped into hot oil in an untidy lump, and dipped in a thin sugar glaze while still hot.'),
((SELECT id FROM dishes WHERE slug='apple-fritter'),5,'A craggy, glazed slab of fried dough shot through with cinnamon and chopped apple.'),
((SELECT id FROM dishes WHERE slug='zeppole'),1,'From the boot-shaped country in southern Europe, and it belongs to one particular day on the calendar.'),
((SELECT id FROM dishes WHERE slug='zeppole'),2,'Naples claims it and ties it to the feast of Saint Joseph on the 19th of March, which is also Italy''s Father''s Day; convent kitchens are usually credited with the recipe.'),
((SELECT id FROM dishes WHERE slug='zeppole'),3,'Bakery lines run down the block in Italian-American neighborhoods every March, and the same fried dough turns up at every summer street feast.'),
((SELECT id FROM dishes WHERE slug='zeppole'),4,'Choux pastry is piped into a ring, fried or baked until hollow, then filled with vanilla cream and topped with a candied sour cherry and a snow of powdered sugar.'),
((SELECT id FROM dishes WHERE slug='zeppole'),5,'A fried ring of choux pastry piped full of cream and crowned with a candied cherry, sold for Saint Joseph''s Day.');
